var sb = new System.Text.StringBuilder();
var sc = UnityEngine.SceneManagement.SceneManager.GetActiveScene();
sb.Append("scene=" + sc.name + " dirty=" + (UnityEditor.SceneManagement.EditorSceneManager.GetSceneManagerSetup().Length)).Append("\n");
foreach (var root in sc.GetRootGameObjects())
{
    foreach (var t in root.GetComponentsInChildren<Transform>(true))
    {
        string p = t.name;
        var par = t.parent;
        int depth = 0;
        while (par != null) { p = par.name + "/" + p; par = par.parent; depth++; }
        var rt = t as RectTransform;
        string extra = "";
        if (rt != null) extra = " anchored=" + rt.anchoredPosition.x + "," + rt.anchoredPosition.y;
        sb.Append("  ").Append(p).Append(" active=").Append(t.gameObject.activeSelf).Append(extra).Append("\n");
    }
}
return sb.ToString();
